#!/usr/bin/env node
import { randomBytes } from "node:crypto";
import { serve } from "@hono/node-server";
import { Hono } from "hono";
import {
  buildAuthUrl,
  exchangeCode,
  generateCodeChallenge,
  generateCodeVerifier,
  REDIRECT_PORT,
  REDIRECT_URI,
} from "./lib/oauth.mts";
import { getMe } from "./lib/x-api.mts";
import { saveTokens } from "./lib/storage.mts";

const clientId = process.env.X_CLIENT_ID;
const clientSecret = process.env.X_CLIENT_SECRET;
if (!clientId || !clientSecret) {
  console.error("Missing X_CLIENT_ID or X_CLIENT_SECRET in .env");
  process.exit(1);
}

const codeVerifier = generateCodeVerifier();
const codeChallenge = generateCodeChallenge(codeVerifier);
const state = randomBytes(16).toString("hex");

const authUrl = buildAuthUrl({ clientId, state, codeChallenge });

const app = new Hono();

const codePromise = new Promise<string>((resolve, reject) => {
  app.get("/callback", (c) => {
    const returnedState = c.req.query("state");
    const code = c.req.query("code");
    const error = c.req.query("error");
    if (error) {
      reject(new Error(`OAuth error: ${error}`));
      return c.text(`OAuth error: ${error}`, 400);
    }
    if (returnedState !== state) {
      reject(new Error("State mismatch"));
      return c.text("State mismatch", 400);
    }
    if (!code) {
      reject(new Error("No code in callback"));
      return c.text("Missing code", 400);
    }
    resolve(code);
    return c.text("Authorized. You can close this tab.");
  });
});

const server = serve({ fetch: app.fetch, port: REDIRECT_PORT });

console.log("Open this URL in your browser to authorize:\n");
console.log(authUrl);
console.log(`\nWaiting for callback on ${REDIRECT_URI} ...`);

try {
  const code = await codePromise;
  const tokens = await exchangeCode({
    clientId,
    clientSecret,
    code,
    codeVerifier,
  });
  const me = await getMe(tokens.access_token);
  await saveTokens({
    access_token: tokens.access_token,
    refresh_token: tokens.refresh_token,
    expires_at: Date.now() + tokens.expires_in * 1000,
    user_id: me.data.id,
    username: me.data.username,
  });
  console.log(`\nAuthorized as @${me.data.username} (id: ${me.data.id}).`);
  console.log("Tokens saved to data/x-tokens.json.");
} catch (err) {
  console.error(err);
  process.exitCode = 1;
} finally {
  server.close();
}

import { randomBytes, createHash } from "node:crypto";
import { loadTokens, saveTokens, type Tokens } from "./storage.mts";

const TOKEN_URL = "https://api.x.com/2/oauth2/token";
const AUTH_URL = "https://x.com/i/oauth2/authorize";
export const REDIRECT_PORT = 47891;
export const REDIRECT_URI = `http://localhost:${REDIRECT_PORT}/callback`;
export const SCOPES = ["tweet.read", "users.read", "offline.access"];

const base64url = (buf: Buffer) =>
  buf.toString("base64").replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");

export const generateCodeVerifier = () => base64url(randomBytes(32));
export const generateCodeChallenge = (verifier: string) =>
  base64url(createHash("sha256").update(verifier).digest());

export function buildAuthUrl(opts: {
  clientId: string;
  state: string;
  codeChallenge: string;
}): string {
  const params = new URLSearchParams({
    response_type: "code",
    client_id: opts.clientId,
    redirect_uri: REDIRECT_URI,
    scope: SCOPES.join(" "),
    state: opts.state,
    code_challenge: opts.codeChallenge,
    code_challenge_method: "S256",
  });
  return `${AUTH_URL}?${params.toString()}`;
}

function basicAuth(clientId: string, clientSecret: string): string {
  return "Basic " + Buffer.from(`${clientId}:${clientSecret}`).toString("base64");
}

type TokenResponse = {
  access_token: string;
  refresh_token: string;
  expires_in: number;
  token_type: string;
  scope: string;
};

export async function exchangeCode(opts: {
  clientId: string;
  clientSecret: string;
  code: string;
  codeVerifier: string;
}): Promise<TokenResponse> {
  const body = new URLSearchParams({
    grant_type: "authorization_code",
    code: opts.code,
    redirect_uri: REDIRECT_URI,
    code_verifier: opts.codeVerifier,
    client_id: opts.clientId,
  });
  const res = await fetch(TOKEN_URL, {
    method: "POST",
    headers: {
      "Content-Type": "application/x-www-form-urlencoded",
      Authorization: basicAuth(opts.clientId, opts.clientSecret),
    },
    body,
  });
  if (!res.ok) {
    throw new Error(`Token exchange failed: ${res.status} ${await res.text()}`);
  }
  return (await res.json()) as TokenResponse;
}

export async function refreshTokens(opts: {
  clientId: string;
  clientSecret: string;
  refreshToken: string;
}): Promise<TokenResponse> {
  const body = new URLSearchParams({
    grant_type: "refresh_token",
    refresh_token: opts.refreshToken,
    client_id: opts.clientId,
  });
  const res = await fetch(TOKEN_URL, {
    method: "POST",
    headers: {
      "Content-Type": "application/x-www-form-urlencoded",
      Authorization: basicAuth(opts.clientId, opts.clientSecret),
    },
    body,
  });
  if (!res.ok) {
    throw new Error(`Token refresh failed: ${res.status} ${await res.text()}`);
  }
  return (await res.json()) as TokenResponse;
}

export async function getValidAccessToken(): Promise<Tokens> {
  const tokens = await loadTokens();
  if (!tokens) {
    throw new Error("No tokens found. Run `npm run x:auth` first.");
  }
  const skewMs = 60_000;
  if (Date.now() < tokens.expires_at - skewMs) return tokens;

  const clientId = process.env.X_CLIENT_ID;
  const clientSecret = process.env.X_CLIENT_SECRET;
  if (!clientId || !clientSecret) {
    throw new Error("X_CLIENT_ID and X_CLIENT_SECRET must be set in .env");
  }
  const refreshed = await refreshTokens({
    clientId,
    clientSecret,
    refreshToken: tokens.refresh_token,
  });
  const updated: Tokens = {
    ...tokens,
    access_token: refreshed.access_token,
    refresh_token: refreshed.refresh_token,
    expires_at: Date.now() + refreshed.expires_in * 1000,
  };
  await saveTokens(updated);
  return updated;
}

const API_BASE = "https://api.todoist.com/api/v1";

type Paginated<T> = { results: T[]; next_cursor: string | null };

export type TodoistProject = {
  id: string;
  name: string;
  color: string;
  is_favorite: boolean;
};

export type TodoistSection = {
  id: string;
  name: string;
  project_id: string;
  order: number;
};

export type TodoistTask = {
  id: string;
  content: string;
  project_id: string;
  section_id: string | null;
};

export interface TodoistApi {
  listProjects(): Promise<TodoistProject[]>;
  listSections(projectId: string): Promise<TodoistSection[]>;
  addTask(args: {
    content: string;
    projectId: string;
    sectionId: string;
  }): Promise<TodoistTask>;
  addTriageQueueEntry(args: {
    content: string;
    planningProjectId: string;
  }): Promise<TodoistTask>;
  deleteTask(taskId: string): Promise<void>;
}

async function todoistGet<T>(path: string, token: string, params?: Record<string, string>): Promise<T> {
  const url = new URL(`${API_BASE}${path}`);
  if (params) {
    for (const [k, v] of Object.entries(params)) url.searchParams.set(k, v);
  }
  const res = await fetch(url, {
    headers: { Authorization: `Bearer ${token}` },
  });
  if (!res.ok) {
    throw new Error(`Todoist API ${path} failed: ${res.status} ${await res.text()}`);
  }
  return (await res.json()) as T;
}

async function todoistPost<T>(path: string, token: string, body: Record<string, unknown>): Promise<T> {
  const res = await fetch(`${API_BASE}${path}`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${token}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify(body),
  });
  if (!res.ok) {
    throw new Error(`Todoist API POST ${path} failed: ${res.status} ${await res.text()}`);
  }
  return (await res.json()) as T;
}

async function collectPaginated<T>(
  path: string,
  token: string,
  params?: Record<string, string>,
): Promise<T[]> {
  const all: T[] = [];
  let cursor: string | null = null;
  do {
    const query: Record<string, string> = { ...(params ?? {}) };
    if (cursor) query.cursor = cursor;
    const page = await todoistGet<Paginated<T>>(path, token, query);
    all.push(...page.results);
    cursor = page.next_cursor;
  } while (cursor);
  return all;
}

export function createTodoistApi(token: string): TodoistApi {
  return {
    async listProjects() {
      return collectPaginated<TodoistProject>("/projects", token);
    },

    async listSections(projectId: string) {
      return collectPaginated<TodoistSection>("/sections", token, { project_id: projectId });
    },

    async addTask(args) {
      if (!args.sectionId) {
        throw new Error(
          "addTask requires a sectionId. To create a Triage Queue entry in #Planning with no section, use addTriageQueueEntry instead (see ADR-0001).",
        );
      }
      return todoistPost<TodoistTask>("/tasks", token, {
        content: args.content,
        project_id: args.projectId,
        section_id: args.sectionId,
      });
    },

    async addTriageQueueEntry(args) {
      return todoistPost<TodoistTask>("/tasks", token, {
        content: args.content,
        project_id: args.planningProjectId,
      });
    },

    async deleteTask(taskId: string) {
      const res = await fetch(`${API_BASE}/tasks/${taskId}`, {
        method: "DELETE",
        headers: { Authorization: `Bearer ${token}` },
      });
      if (!res.ok) {
        throw new Error(
          `Todoist API DELETE /tasks/${taskId} failed: ${res.status} ${await res.text()}`,
        );
      }
    },
  };
}

export function getTodoistToken(): string {
  const token = process.env.TODOIST_API_TOKEN;
  if (!token) {
    throw new Error(
      "TODOIST_API_TOKEN is not set. Add it to .env — get your token from https://app.todoist.com/app/settings/integrations/developer",
    );
  }
  return token;
}

export type ReferencedTweet = {
  type: "replied_to" | "quoted" | "retweeted";
  id: string;
};

export type Tweet = {
  id: string;
  text: string;
  author_id: string;
  created_at: string;
  public_metrics: {
    retweet_count: number;
    reply_count: number;
    like_count: number;
    quote_count: number;
    impression_count?: number;
  };
  referenced_tweets?: ReferencedTweet[];
};

export type Mention = Tweet;

export type MentionAuthor = {
  id: string;
  username: string;
  name: string;
  verified: boolean;
};

export type MentionsResponse = {
  data?: Mention[];
  includes?: { users?: MentionAuthor[]; tweets?: Tweet[] };
  meta: {
    newest_id?: string;
    oldest_id?: string;
    result_count: number;
    next_token?: string;
  };
};

export type TweetsLookupResponse = {
  data?: Tweet[];
  includes?: { users?: MentionAuthor[]; tweets?: Tweet[] };
};

export type Me = {
  data: { id: string; username: string; name: string };
};

const API_BASE = "https://api.x.com/2";

const TWEET_FIELDS = "created_at,public_metrics,author_id,referenced_tweets";
const TWEET_EXPANSIONS = "author_id,referenced_tweets.id,referenced_tweets.id.author_id";
const USER_FIELDS = "username,verified,name";

async function xGet<T>(
  path: string,
  accessToken: string,
  params?: Record<string, string>,
): Promise<T> {
  const url = new URL(`${API_BASE}${path}`);
  if (params)
    for (const [k, v] of Object.entries(params)) url.searchParams.set(k, v);
  const res = await fetch(url, {
    headers: { Authorization: `Bearer ${accessToken}` },
  });
  if (!res.ok) {
    throw new Error(`X API ${path} failed: ${res.status} ${await res.text()}`);
  }
  return (await res.json()) as T;
}

export const getMe = (accessToken: string) =>
  xGet<Me>("/users/me", accessToken);

export function getMentions(opts: {
  accessToken: string;
  userId: string;
  sinceId?: string;
  paginationToken?: string;
}): Promise<MentionsResponse> {
  const params: Record<string, string> = {
    max_results: "5",
    "tweet.fields": TWEET_FIELDS,
    expansions: TWEET_EXPANSIONS,
    "user.fields": USER_FIELDS,
  };
  if (opts.sinceId) params.since_id = opts.sinceId;
  if (opts.paginationToken) params.pagination_token = opts.paginationToken;
  return xGet<MentionsResponse>(
    `/users/${opts.userId}/mentions`,
    opts.accessToken,
    params,
  );
}

export function searchQuotes(opts: {
  accessToken: string;
  username: string;
  sinceId?: string;
  paginationToken?: string;
}): Promise<MentionsResponse> {
  const params: Record<string, string> = {
    query: `quotes_of:${opts.username}`,
    max_results: "10",
    "tweet.fields": TWEET_FIELDS,
    expansions: TWEET_EXPANSIONS,
    "user.fields": USER_FIELDS,
  };
  if (opts.sinceId) params.since_id = opts.sinceId;
  if (opts.paginationToken) params.next_token = opts.paginationToken;
  return xGet<MentionsResponse>("/tweets/search/recent", opts.accessToken, params);
}

export type UserTweetsResponse = {
  data?: Tweet[];
  includes?: { users?: MentionAuthor[]; tweets?: Tweet[] };
  meta: {
    newest_id?: string;
    oldest_id?: string;
    result_count: number;
    next_token?: string;
  };
};

export function getUserTweets(opts: {
  accessToken: string;
  userId: string;
  startTime: string;
  paginationToken?: string;
}): Promise<UserTweetsResponse> {
  const params: Record<string, string> = {
    max_results: "100",
    exclude: "retweets,replies",
    start_time: opts.startTime,
    "tweet.fields": TWEET_FIELDS,
    expansions: TWEET_EXPANSIONS,
    "user.fields": USER_FIELDS,
  };
  if (opts.paginationToken) params.pagination_token = opts.paginationToken;
  return xGet<UserTweetsResponse>(
    `/users/${opts.userId}/tweets`,
    opts.accessToken,
    params,
  );
}

export function getTweets(opts: {
  accessToken: string;
  ids: string[];
}): Promise<TweetsLookupResponse> {
  if (opts.ids.length === 0 || opts.ids.length > 100) {
    throw new Error(`getTweets: ids.length must be 1..100, got ${opts.ids.length}`);
  }
  return xGet<TweetsLookupResponse>("/tweets", opts.accessToken, {
    ids: opts.ids.join(","),
    "tweet.fields": TWEET_FIELDS,
    expansions: TWEET_EXPANSIONS,
    "user.fields": USER_FIELDS,
  });
}

import { describe, it, beforeEach, afterEach } from "node:test";
import assert from "node:assert/strict";
import { mkdtemp, rm, writeFile, readFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { execFile } from "node:child_process";
import { promisify } from "node:util";

const execFileAsync = promisify(execFile);

const SCRIPT = new URL("./close-mention.mts", import.meta.url).pathname;

async function run(
  mentionIds: string[] | undefined,
  storePath: string,
): Promise<{ code: number; stdout: string; stderr: string }> {
  const args = ["--experimental-strip-types", "--no-warnings", SCRIPT];
  if (mentionIds !== undefined) args.push(...mentionIds);
  try {
    const { stdout, stderr } = await execFileAsync("node", args, {
      env: { ...process.env, MENTION_STORE_PATH: storePath },
    });
    return { code: 0, stdout, stderr };
  } catch (err: unknown) {
    const e = err as { code: number; stdout: string; stderr: string };
    return { code: e.code, stdout: e.stdout, stderr: e.stderr };
  }
}

function storeWith(mentions: Record<string, unknown>): string {
  return JSON.stringify(mentions, null, 2) + "\n";
}

describe("close-mention CLI", () => {
  let tmpDir: string;
  let storePath: string;

  beforeEach(async () => {
    tmpDir = await mkdtemp(join(tmpdir(), "close-mention-test-"));
    storePath = join(tmpDir, "x-mentions.json");
  });

  afterEach(async () => {
    await rm(tmpDir, { recursive: true, force: true });
  });

  it("closes an open mention — exit 0, silent stdout", async () => {
    await writeFile(
      storePath,
      storeWith({
        "100": {
          id: "100",
          fetched_at: "2026-05-08T10:00:00.000Z",
          closed_at: null,
          text: "hello",
          author_username: "alice",
          author_name: "Alice",
          created_at: "2026-05-08T09:00:00.000Z",
          parent_ref_id: null,
        },
      }),
    );

    const result = await run(["100"], storePath);
    assert.equal(result.code, 0, `expected exit 0, got ${result.code}`);
    assert.equal(result.stdout, "", "expected silent stdout");

    const data = JSON.parse(await readFile(storePath, "utf8"));
    assert.notEqual(data["100"].closed_at, null, "closed_at should be set");
  });

  it("exits non-zero for unknown mention id", async () => {
    await writeFile(storePath, storeWith({}));

    const result = await run(["nonexistent"], storePath);
    assert.notEqual(result.code, 0, "expected non-zero exit");
    assert.match(result.stderr, /nonexistent/, "error should mention the id");
  });

  it("exits zero for already-closed mention — idempotent", async () => {
    await writeFile(
      storePath,
      storeWith({
        "200": {
          id: "200",
          fetched_at: "2026-05-08T10:00:00.000Z",
          closed_at: "2026-05-08T11:00:00.000Z",
          text: "hello",
          author_username: "bob",
          author_name: "Bob",
          created_at: "2026-05-08T09:00:00.000Z",
          parent_ref_id: null,
        },
      }),
    );

    const originalData = await readFile(storePath, "utf8");
    const result = await run(["200"], storePath);
    assert.equal(result.code, 0, "expected exit 0 for already-closed");
    assert.equal(result.stdout, "", "expected silent stdout");

    const afterData = await readFile(storePath, "utf8");
    assert.equal(afterData, originalData, "file should not be rewritten");
  });

  it("closes multiple mentions in one invocation", async () => {
    await writeFile(
      storePath,
      storeWith({
        "100": {
          id: "100",
          fetched_at: "2026-05-08T10:00:00.000Z",
          closed_at: null,
          text: "hello",
          author_username: "alice",
          author_name: "Alice",
          created_at: "2026-05-08T09:00:00.000Z",
          parent_ref_id: null,
        },
        "101": {
          id: "101",
          fetched_at: "2026-05-08T10:00:00.000Z",
          closed_at: null,
          text: "hi",
          author_username: "bob",
          author_name: "Bob",
          created_at: "2026-05-08T09:30:00.000Z",
          parent_ref_id: null,
        },
      }),
    );

    const result = await run(["100", "101"], storePath);
    assert.equal(result.code, 0, `expected exit 0, got ${result.code}`);

    const data = JSON.parse(await readFile(storePath, "utf8"));
    assert.notEqual(data["100"].closed_at, null, "100 should be closed");
    assert.notEqual(data["101"].closed_at, null, "101 should be closed");
  });

  it("closes valid ids and reports unknown ones with non-zero exit", async () => {
    await writeFile(
      storePath,
      storeWith({
        "100": {
          id: "100",
          fetched_at: "2026-05-08T10:00:00.000Z",
          closed_at: null,
          text: "hello",
          author_username: "alice",
          author_name: "Alice",
          created_at: "2026-05-08T09:00:00.000Z",
          parent_ref_id: null,
        },
      }),
    );

    const result = await run(["100", "nonexistent"], storePath);
    assert.notEqual(result.code, 0, "expected non-zero exit");
    assert.match(result.stderr, /nonexistent/);

    const data = JSON.parse(await readFile(storePath, "utf8"));
    assert.notEqual(data["100"].closed_at, null, "valid id should still close");
  });

  it("exits non-zero when no mention-id argument is provided", async () => {
    await writeFile(storePath, storeWith({}));

    const result = await run(undefined, storePath);
    assert.notEqual(result.code, 0, "expected non-zero exit");
    assert.match(result.stderr, /usage/i, "should print usage hint");
  });

  describe("range syntax (id..id)", () => {
    function openMention(id: string): Record<string, unknown> {
      return {
        id,
        fetched_at: "2026-05-08T10:00:00.000Z",
        closed_at: null,
        text: `tweet ${id}`,
        author_username: "alice",
        author_name: "Alice",
        created_at: "2026-05-08T09:00:00.000Z",
        parent_ref_id: null,
      };
    }

    function closedMention(id: string): Record<string, unknown> {
      return { ...openMention(id), closed_at: "2026-05-08T11:00:00.000Z" };
    }

    it("closes all open mentions in the inclusive range", async () => {
      await writeFile(
        storePath,
        storeWith({
          "100": openMention("100"),
          "150": openMention("150"),
          "200": openMention("200"),
          "300": openMention("300"),
        }),
      );

      const result = await run(["100..200"], storePath);
      assert.equal(result.code, 0, `expected exit 0, got ${result.code}: ${result.stderr}`);
      assert.match(result.stderr, /3 mentions/, "summary should report 3 closed");

      const data = JSON.parse(await readFile(storePath, "utf8"));
      assert.notEqual(data["100"].closed_at, null);
      assert.notEqual(data["150"].closed_at, null);
      assert.notEqual(data["200"].closed_at, null);
      assert.equal(data["300"].closed_at, null, "outside-range stays open");
    });

    it("range with single-id span (id..id) closes only that id", async () => {
      await writeFile(
        storePath,
        storeWith({ "100": openMention("100"), "200": openMention("200") }),
      );

      const result = await run(["100..100"], storePath);
      assert.equal(result.code, 0);

      const data = JSON.parse(await readFile(storePath, "utf8"));
      assert.notEqual(data["100"].closed_at, null);
      assert.equal(data["200"].closed_at, null);
    });

    it("range matching only already-closed mentions errors", async () => {
      await writeFile(
        storePath,
        storeWith({
          "100": closedMention("100"),
          "150": closedMention("150"),
          "300": openMention("300"),
        }),
      );

      const result = await run(["100..200"], storePath);
      assert.notEqual(result.code, 0, "expected non-zero exit");
      assert.match(result.stderr, /no open mentions in range/i);
    });

    it("range matching no stored mentions errors", async () => {
      await writeFile(storePath, storeWith({ "1000": openMention("1000") }));

      const result = await run(["100..200"], storePath);
      assert.notEqual(result.code, 0);
      assert.match(result.stderr, /100\.\.200/);
    });

    it("reversed range (high..low) errors", async () => {
      await writeFile(storePath, storeWith({ "150": openMention("150") }));

      const result = await run(["200..100"], storePath);
      assert.notEqual(result.code, 0);
      assert.match(result.stderr, /left endpoint/i);
