import { describe, it, beforeEach, afterEach } from "node:test";
import assert from "node:assert/strict";
import { mkdtemp, rm, readFile, writeFile, readdir } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { JsonFileMentionStore, type StoredMention } from "./mention-store.mts";

function makeMention(overrides: Partial<StoredMention> = {}): StoredMention {
  return {
    id: "1",
    kind: "reply",
    fetched_at: "2026-05-08T10:00:00.000Z",
    closed_at: null,
    text: "hello @matt",
    author_username: "alice",
    author_name: "Alice",
    created_at: "2026-05-08T09:00:00.000Z",
    parent_ref_id: null,
    ...overrides,
  };
}

describe("JsonFileMentionStore", () => {
  let tmpDir: string;
  let filePath: string;
  let store: JsonFileMentionStore;

  beforeEach(async () => {
    tmpDir = await mkdtemp(join(tmpdir(), "mention-store-test-"));
    filePath = join(tmpDir, "x-mentions.json");
    store = new JsonFileMentionStore(filePath);
  });

  afterEach(async () => {
    await rm(tmpDir, { recursive: true, force: true });
  });

  describe("upsertOpen", () => {
    it("inserts a new mention", async () => {
      const m = makeMention({ id: "100" });
      await store.upsertOpen(m);
      const result = await store.getById("100");
      assert.deepEqual(result, m);
    });

    it("is idempotent — upserting same id twice yields one row", async () => {
      const m = makeMention({ id: "100" });
      await store.upsertOpen(m);
      await store.upsertOpen(m);
      const all = await store.listOpen();
      assert.equal(all.length, 1);
    });

    it("does not reopen a closed mention", async () => {
      const m = makeMention({ id: "100" });
      await store.upsertOpen(m);
      await store.close("100");
      await store.upsertOpen(m);
      const result = await store.getById("100");
      assert.notEqual(result!.closed_at, null);
    });

    it("updates fields when re-upserting an open mention", async () => {
      await store.upsertOpen(makeMention({ id: "100", text: "old text" }));
      await store.upsertOpen(makeMention({ id: "100", text: "new text" }));
      const result = await store.getById("100");
      assert.equal(result!.text, "new text");
      const all = await store.listOpen();
      assert.equal(all.length, 1);
    });
  });

  describe("listOpen", () => {
    it("returns empty array for fresh store", async () => {
      const result = await store.listOpen();
      assert.deepEqual(result, []);
    });

    it("returns only open mentions", async () => {
      await store.upsertOpen(makeMention({ id: "1" }));
      await store.upsertOpen(makeMention({ id: "2" }));
      await store.close("1");
      const open = await store.listOpen();
      assert.equal(open.length, 1);
      assert.equal(open[0]!.id, "2");
    });

    it("returns mentions oldest-first by created_at", async () => {
      await store.upsertOpen(
        makeMention({ id: "2", created_at: "2026-05-08T11:00:00.000Z" }),
      );
      await store.upsertOpen(
        makeMention({ id: "1", created_at: "2026-05-08T09:00:00.000Z" }),
      );
      const open = await store.listOpen();
      assert.equal(open[0]!.id, "1");
      assert.equal(open[1]!.id, "2");
    });
  });

  describe("getById", () => {
    it("returns null for unknown id", async () => {
      const result = await store.getById("nonexistent");
      assert.equal(result, null);
    });

    it("returns the mention by id", async () => {
      const m = makeMention({ id: "42" });
      await store.upsertOpen(m);
      const result = await store.getById("42");
      assert.deepEqual(result, m);
    });
  });

  describe("close", () => {
    it("transitions a mention out of the open set", async () => {
      await store.upsertOpen(makeMention({ id: "1" }));
      await store.close("1");
      const open = await store.listOpen();
      assert.equal(open.length, 0);
    });

    it("sets closed_at to a non-null ISO string", async () => {
      await store.upsertOpen(makeMention({ id: "1" }));
      await store.close("1");
      const m = await store.getById("1");
      assert.notEqual(m!.closed_at, null);
      assert.doesNotThrow(() => new Date(m!.closed_at!));
    });

    it("is a no-op for unknown id", async () => {
      await assert.doesNotReject(() => store.close("nonexistent"));
    });
  });

  describe("atomic write durability", () => {
    it("writes valid JSON to disk", async () => {
      await store.upsertOpen(makeMention({ id: "1" }));
      const raw = await readFile(filePath, "utf8");
      assert.doesNotThrow(() => JSON.parse(raw));
    });

    it("persists across store instances", async () => {
      await store.upsertOpen(makeMention({ id: "1" }));
      const store2 = new JsonFileMentionStore(filePath);
      const result = await store2.getById("1");
      assert.equal(result!.id, "1");
    });

    it("never leaves a partially-written destination file (uses tmp+rename)", async () => {
      // Pre-populate the destination so we can detect mid-write corruption.
      await writeFile(filePath, JSON.stringify({}, null, 2), "utf8");

      // Stub writeFile is hard from outside; instead, monkey-patch the
      // destination to be a directory the store can't overwrite directly.
      // The store writes to a tmp file first and renames — so even if the
      // process were killed mid-stream, the destination still parses.
      // Verify by triggering writes and asserting destination always parses.
      for (let i = 0; i < 10; i++) {
        await store.upsertOpen(makeMention({ id: String(i) }));
        const raw = await readFile(filePath, "utf8");
        assert.doesNotThrow(
          () => JSON.parse(raw),
          `destination must parse after write ${i}`,
        );
      }
    });

    it("does not leave tmp files behind on success", async () => {
      await store.upsertOpen(makeMention({ id: "1" }));
      await store.upsertOpen(makeMention({ id: "2" }));
      await store.close("1");
      const entries = await readdir(tmpDir);
      const stragglers = entries.filter((e) => e.startsWith(".tmp-"));
      assert.deepEqual(stragglers, []);
    });
  });
});

import { readFile, writeFile, mkdir } from "node:fs/promises";
import { dirname } from "node:path";
import type { Tweet, MentionAuthor } from "./x-api.mts";

export type Tokens = {
  access_token: string;
  refresh_token: string;
  expires_at: number;
  user_id: string;
  username: string;
};

export type State = {
  last_seen_reply_id?: string;
  last_seen_quote_id?: string;
  last_fetched_at?: string;
};

type RawState = State & { last_seen_mention_id?: string };

export type CachedTweet = Tweet & { author: MentionAuthor | null };
export type TweetCache = Record<string, CachedTweet>;

const TOKENS_PATH = "data/x-tokens.json";
const STATE_PATH = "data/x-state.json";
const TWEET_CACHE_PATH = "data/x-tweet-cache.json";

async function readJson<T>(path: string): Promise<T | null> {
  try {
    const raw = await readFile(path, "utf8");
    return JSON.parse(raw) as T;
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === "ENOENT") return null;
    throw err;
  }
}

async function writeJson(path: string, value: unknown): Promise<void> {
  await mkdir(dirname(path), { recursive: true });
  await writeFile(path, JSON.stringify(value, null, 2) + "\n", "utf8");
}

export const loadTokens = () => readJson<Tokens>(TOKENS_PATH);
export const saveTokens = (t: Tokens) => writeJson(TOKENS_PATH, t);
export const loadState = async (): Promise<State> => {
  const raw = (await readJson<RawState>(STATE_PATH)) ?? {};
  if (raw.last_seen_mention_id && !raw.last_seen_reply_id) {
    raw.last_seen_reply_id = raw.last_seen_mention_id;
  }
  delete raw.last_seen_mention_id;
  return raw;
};
export const saveState = (s: State) => writeJson(STATE_PATH, s);

export const loadTweetCache = async (): Promise<TweetCache> =>
  (await readJson<TweetCache>(TWEET_CACHE_PATH)) ?? {};
export const saveTweetCache = (c: TweetCache) => writeJson(TWEET_CACHE_PATH, c);

import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { renderThread } from "./mention-renderer.mts";
import type { MentionThread, ThreadTreeNode } from "./thread-builder.mts";
import type { CachedTweet } from "./storage.mts";

function makeCachedTweet(
  overrides: Partial<CachedTweet> & { id: string },
): CachedTweet {
  return {
    text: "tweet text",
    author_id: "a1",
    created_at: "2026-05-08T09:00:00.000Z",
    public_metrics: {
      retweet_count: 0,
      reply_count: 0,
      like_count: 0,
      quote_count: 0,
    },
    author: { id: "a1", username: "alice", name: "Alice", verified: false },
    ...overrides,
  };
}

function makeNode(
  overrides: Partial<ThreadTreeNode> & { id: string },
): ThreadTreeNode {
  return {
    tweet: makeCachedTweet({ id: overrides.id }),
    status: "context",
    children: [],
    ...overrides,
  };
}

function stripAnsi(s: string): string {
  return s.replace(/\x1b\[\d+m/g, "");
}

function makeThread(root: ThreadTreeNode): MentionThread {
  return {
    rootKey: root.id,
    rootResolved: root.tweet !== null,
    newestOpenAt: "2026-05-08T10:00:00.000Z",
    root,
  };
}

describe("renderThread", () => {
  it("renders a single-node thread (root only)", () => {
    const thread = makeThread(
      makeNode({
        id: "1",
        tweet: makeCachedTweet({ id: "1", text: "Hello world" }),
      }),
    );
    const out = stripAnsi(renderThread(thread));
    assert.ok(out.includes("@alice"));
    assert.ok(out.includes("Hello world"));
    assert.ok(out.includes("[1]"));
  });

  it("renders a parent with two sibling children using box-drawing", () => {
    const thread = makeThread(
      makeNode({
        id: "1",
        tweet: makeCachedTweet({ id: "1", text: "Root" }),
        children: [
          makeNode({
            id: "2",
            tweet: makeCachedTweet({
              id: "2",
              text: "First child",
              author: {
                id: "b",
                username: "bob",
                name: "Bob",
                verified: false,
              },
            }),
            status: "open",
          }),
          makeNode({
            id: "3",
            tweet: makeCachedTweet({
              id: "3",
              text: "Second child",
              author: {
                id: "c",
                username: "carol",
                name: "Carol",
                verified: false,
              },
            }),
            status: "new",
          }),
        ],
      }),
    );
    const out = stripAnsi(renderThread(thread));
    assert.ok(out.includes("├─ "), "first sibling uses ├─");
    assert.ok(out.includes("└─ "), "last sibling uses └─");
    assert.ok(out.includes("● open"), "open marker present");
    assert.ok(out.includes("★ new"), "new marker present");
    assert.ok(out.includes("@bob"));
    assert.ok(out.includes("@carol"));
  });

  it("renders nested children with continuation prefix │", () => {
    const thread = makeThread(
      makeNode({
        id: "1",
        tweet: makeCachedTweet({ id: "1" }),
        children: [
          makeNode({
            id: "2",
            tweet: makeCachedTweet({ id: "2" }),
            children: [
              makeNode({
                id: "3",
                tweet: makeCachedTweet({ id: "3" }),
                status: "new",
              }),
            ],
          }),
          makeNode({ id: "4", tweet: makeCachedTweet({ id: "4" }) }),
        ],
      }),
    );
    const out = stripAnsi(renderThread(thread));
    // child of non-last sibling should be prefixed with │
    assert.ok(/│  └─ /.test(out), "continuation prefix used for nested child");
  });

  it("renders an unresolved root as a gap placeholder", () => {
    const thread: MentionThread = {
      rootKey: "999",
      rootResolved: false,
      newestOpenAt: "2026-05-08T10:00:00.000Z",
      root: {
        id: "999",
        tweet: null,
        status: "context",
        children: [
          {
            id: "2",
            tweet: makeCachedTweet({ id: "2", text: "Hangs from gap" }),
            status: "new",
            children: [],
          },
        ],
      },
    };
    const out = stripAnsi(renderThread(thread));
    assert.ok(out.includes("unresolved tweet 999"));
    assert.ok(out.includes("Hangs from gap"));
  });

  it("flattens multi-line tweet text", () => {
    const thread = makeThread(
      makeNode({
        id: "1",
        tweet: makeCachedTweet({ id: "1", text: "line one\n\nline two" }),
      }),
    );
    const out = stripAnsi(renderThread(thread));
    assert.ok(out.includes("line one line two"));
    assert.ok(!out.includes("line one\n"));
  });

  it("renders [QUOTE] label on quote-kind nodes", () => {
    const thread = makeThread(
      makeNode({
        id: "100",
        tweet: makeCachedTweet({ id: "100", text: "Matt's tweet" }),
        children: [
          makeNode({
            id: "200",
            tweet: makeCachedTweet({ id: "200", text: "Quoting Matt" }),
            status: "open",
            kind: "quote",
          }),
        ],
      }),
    );
    const out = stripAnsi(renderThread(thread));
    assert.ok(out.includes("[QUOTE]"), "quote label rendered");
  });

  it("does not render [QUOTE] on reply-kind or unspecified nodes", () => {
    const thread = makeThread(
      makeNode({
        id: "1",
        tweet: makeCachedTweet({ id: "1" }),
        children: [
          makeNode({
            id: "2",
            tweet: makeCachedTweet({ id: "2" }),
            status: "open",
            kind: "reply",
          }),
        ],
      }),
    );
    const out = stripAnsi(renderThread(thread));
    assert.ok(!out.includes("[QUOTE]"), "no quote label on reply");
  });

  it("emits no marker for context nodes", () => {
    const thread = makeThread(
      makeNode({ id: "1", tweet: makeCachedTweet({ id: "1" }) }),
    );
    const out = stripAnsi(renderThread(thread));
    assert.ok(!out.includes("★ new"));
    assert.ok(!out.includes("● open"));
  });
});

