  it("renders a quote mention as unresolved when the quoted tweet is missing", () => {
    const cache: TweetCache = {};
    const mentions = [
      makeMention({ id: "200", kind: "quote", parent_ref_id: "100" }),
    ];
    const threads = groupIntoMentionThreads(mentions, cache, new Set());
    assert.equal(threads.length, 1);
    assert.equal(threads[0]!.rootKey, "100");
    assert.equal(threads[0]!.rootResolved, false);
    assert.equal(threads[0]!.root.tweet, null);
    assert.equal(threads[0]!.root.children[0]!.kind, "quote");
  });

  it("does not group quote and reply mentions sharing a parent id", () => {
    const cache: TweetCache = {
      "100": makeCachedTweet({ id: "100", text: "Matt's tweet" }),
      "200": makeCachedTweet({
        id: "200",
        referenced_tweets: [{ type: "replied_to", id: "100" }],
      }),
      "300": makeCachedTweet({
        id: "300",
        referenced_tweets: [{ type: "quoted", id: "100" }],
      }),
    };
    const mentions = [
      makeMention({ id: "200", kind: "reply", parent_ref_id: "100" }),
      makeMention({ id: "300", kind: "quote", parent_ref_id: "100" }),
    ];
    const threads = groupIntoMentionThreads(mentions, cache, new Set());
    assert.equal(threads.length, 2);
  });

  it("prunes branches that don't lead to an open mention", () => {
    // root has two replies; only one has an open mention under it
    const cache: TweetCache = {
      "1": makeCachedTweet({ id: "1", text: "Root" }),
      "2": makeCachedTweet({
        id: "2",
        text: "Reply on the open path",
        referenced_tweets: [{ type: "replied_to", id: "1" }],
      }),
      "3": makeCachedTweet({
        id: "3",
        text: "Unrelated sibling — never mentioned",
        referenced_tweets: [{ type: "replied_to", id: "1" }],
      }),
    };
    const mentions = [makeMention({ id: "2" })];
    const threads = groupIntoMentionThreads(mentions, cache, new Set());
    assert.equal(threads[0]!.root.children.length, 1);
    assert.equal(threads[0]!.root.children[0]!.id, "2");
  });
});

import { readFile, writeFile, mkdir } from "node:fs/promises";
import { dirname } from "node:path";
import type { Tweet } from "./x-api.mts";

export type CachedLikedTweet = Tweet & { fetched_at: string };

export type LikesCache = {
  last_fetched_at?: string;
  username?: string;
  tweets: Record<string, CachedLikedTweet>;
};

const LIKES_CACHE_PATH = "data/x-likes-cache.json";

export const loadLikesCache = async (): Promise<LikesCache> => {
  try {
    const raw = await readFile(LIKES_CACHE_PATH, "utf8");
    return JSON.parse(raw) as LikesCache;
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === "ENOENT") return { tweets: {} };
    throw err;
  }
};

export async function saveLikesCache(cache: LikesCache): Promise<void> {
  await mkdir(dirname(LIKES_CACHE_PATH), { recursive: true });
  await writeFile(
    LIKES_CACHE_PATH,
    JSON.stringify(cache, null, 2) + "\n",
    "utf8",
  );
}

